 font-weight: 700;
 font-size: 16px;
 }

 .modal-actions {
 display: flex;
 gap: 12px;
 }

 .btn-cancel-modal,
 .btn-confirm-modal {
 flex: 1;
 padding: 14px;
 border-radius: 14px;
 font-weight: 600;
 font-size: 15px;
 cursor: pointer;
 transition: all 0.3s ease;
 border: none;
 display: flex;
 align-items: center;
 justify-content: center;
 gap: 8px;
 }

 .btn-cancel-modal {
 background: #f1f5f9;
 color: #475569;
 }

 .btn-cancel-modal:hover {
 background: #e2e8f0;
 transform: translateY(-2px);
 }

 .btn-confirm-modal {
 background: linear-gradient(135deg, #28a745 0%, #20c997 100%);
 color: white;
 box-shadow: 0 4px 12px rgba(40, 167, 69, 0.2);
 }

 .btn-confirm-modal:hover:not(:disabled) {
 transform: translateY(-2px);
 box-shadow: 0 8px 24px rgba(40, 167, 69, 0.3);
 }

 .btn-confirm-modal:disabled {
 opacity: 0.6;
 cursor: wait;
 }

 @media (max-width: 768px) {
 .hero-section h1 { font-size: 36px; }
 .search-grid { grid-template-columns: 1fr; }
 .journey-route { flex-direction: column; text-align: center; }
 .journey-footer { flex-direction: column; }
 .btn-reserve { width: 100%; }
 .modal-content { padding: 30px 25px; }
 }
 </style>
