 <!-- MODAL DE RÉSERVATION -->
 <div id="reservationModal" class="modal-reserve">
 <div class="modal-content">
 <button class="modal-close" onclick="closeReservationModal()">
 <i class="fas fa-times"></i>
 </button>

 <div class="modal-header">
 <h2><i class="fas fa-check-circle"></i> Confirmer la réservation</h2>
 <p>Veuillez sélectionner le nombre de places souhaitées</p>
 </div>

 <div class="places-selector">
 <label>Nombre de places</label>
 <div class="places-input-group">
 <button class="places-btn" id="decrementBtn" onclick="decrementPlaces()">−</button>
 <div class="places-display">
 <span id="selectedPlaces">1</span> place(s)
 </div>
 <button class="places-btn" id="incrementBtn" onclick="incrementPlaces()">+</button>
 </div>
 </div>

 <div class="price-summary">
 <div class="price-row">
 <span>Prix par personne</span>
 <span><span id="pricePerPerson">0</span> DT</span>
 </div>
 <div class="price-row">
 <span>Nombre de places</span>
 <span id="placesCount">0</span>
 </div>
 <div class="price-row">
 <span>Total</span>
 <span><strong><span id="totalPrice">0</span> DT</strong></span>
 </div>
 </div>

 <div class="modal-actions">
 <button class="btn-cancel-modal" onclick="closeReservationModal()">
 <i class="fas fa-times"></i> Annuler
 </button>
 <button class="btn-confirm-modal" id="confirmReservationBtn" onclick="confirmReservation()">
 <i class="fas fa-check-circle"></i> Confirmer
 </button>
 </div>
 </div>
 </div>

 <script>
 // Animation des particules
 const canvas = document.getElementById('particleCanvas');
 if (canvas) {
 canvas.width = canvas.offsetWidth;
 canvas.height = canvas.offsetHeight;
 const ctx = canvas.getContext('2d');
 let particles = [];
 for (let i = 0; i < 50; i++) {
 particles.push({
 x: Math.random() * canvas.width,
 y: Math.random() * canvas.height,
 radius: Math.random() * 3 + 1,
 alpha: Math.random() * 0.5 + 0.2,
 speedX: (Math.random() - 0.5) * 0.5,
 speedY: (Math.random() - 0.5) * 0.5
 });
 }
 function animate() {
 ctx.clearRect(0, 0, canvas.width, canvas.height);
 particles.forEach(p => {
 p.x += p.speedX;
 p.y += p.speedY;
 if (p.x < 0) p.x = canvas.width;
 if (p.x > canvas.width) p.x = 0;
 if (p.y < 0) p.y = canvas.height;
 if (p.y > canvas.height) p.y = 0;
 ctx.beginPath();
 ctx.arc(p.x, p.y, p.radius, 0, Math.PI * 2);
 ctx.fillStyle = `rgba(255, 255, 255, ${p.alpha})`;
 ctx.fill();
 });
 requestAnimationFrame(animate);
 }
 animate();
 window.addEventListener('resize', () => {
 canvas.width = canvas.offsetWidth;
 canvas.height = canvas.offsetHeight;
 });
 }

 // Recherche automatique
 const villeDepart = document.getElementById('villeDepart');
 const destination = document.getElementById('destination');
 const searchForm = document.getElementById('searchForm');

 function performSearch() {
 if (villeDepart.value && destination.value) {
 searchForm.submit();
 }
 }

 villeDepart.addEventListener('change', performSearch);
 destination.addEventListener('change', performSearch);

 // Variables du modal
 let currentTrajetId = null;
 let currentMaxPlaces = 1;
 let currentPricePerPerson = 0;
 let currentSelectedPlaces = 1;

 function openReservationModal(trajetId, maxPlaces, pricePerPerson) {
 currentTrajetId = trajetId;
 currentMaxPlaces = maxPlaces;
 currentPricePerPerson = pricePerPerson;
 currentSelectedPlaces = 1;

 document.getElementById('selectedPlaces').textContent = '1';
 document.getElementById('placesCount').textContent = '1';
 document.getElementById('pricePerPerson').textContent = pricePerPerson;
 document.getElementById('totalPrice').textContent = pricePerPerson;

 updateButtonsState();
 document.getElementById('reservationModal').classList.add('active');
 }

 function closeReservationModal() {
 document.getElementById('reservationModal').classList.remove('active');
 currentTrajetId = null;
 }

 function incrementPlaces() {
 if (currentSelectedPlaces < currentMaxPlaces) {
 currentSelectedPlaces++;
 updateModalDisplay();
 }
 }

 function decrementPlaces() {
 if (currentSelectedPlaces > 1) {
 currentSelectedPlaces--;
 updateModalDisplay();
 }
 }

 function updateModalDisplay() {
 document.getElementById('selectedPlaces').textContent = currentSelectedPlaces;
 document.getElementById('placesCount').textContent = currentSelectedPlaces;
 const total = currentSelectedPlaces * currentPricePerPerson;
 document.getElementById('totalPrice').textContent = total;
 updateButtonsState();
 }

 function updateButtonsState() {
 const incrementBtn = document.getElementById('incrementBtn');
 const decrementBtn = document.getElementById('decrementBtn');

 incrementBtn.disabled = currentSelectedPlaces >= currentMaxPlaces;
 decrementBtn.disabled = currentSelectedPlaces <= 1;
 }

 function confirmReservation() {
 const confirmBtn = document.getElementById('confirmReservationBtn');
 confirmBtn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Chargement...';
 confirmBtn.disabled = true;

 fetch('/reservation/new-ajax', {
 method: 'POST',
 headers: {
 'Content-Type': 'application/json',
 'X-Requested-With': 'XMLHttpRequest'
 },
 body: JSON.stringify({
 trajetId: currentTrajetId,
 nbPlaces: currentSelectedPlaces
 })
 })
 .then(response => response.json())
 .then(data => {
 if (data.success) {
 closeReservationModal();
 showToast('Réservation confirmée avec succès !', 'success');
 setTimeout(() => location.reload(), 1500);
 } else {
 closeReservationModal();
 showToast(data.message || 'Erreur lors de la réservation', 'error');
 }
 })
 .catch(error => {
 closeReservationModal();
 showToast('Erreur réseau. Veuillez réessayer.', 'error');
 })
 .finally(() => {
 confirmBtn.innerHTML = '<i class="fas fa-check-circle"></i> Confirmer';
 confirmBtn.disabled = false;
 });
 }

 function showToast(message, type) {
 let toastContainer = document.getElementById('toast-container');
 if (!toastContainer) {
 toastContainer = document.createElement('div');
 toastContainer.id = 'toast-container';
 toastContainer.style.cssText = 'position: fixed; bottom: 30px; right: 30px; z-index: 3000; display: flex; flex-direction: column; gap: 12px;';
 document.body.appendChild(toastContainer);
 }

 const toast = document.createElement('div');
 toast.style.cssText = `
 background: ${type === 'success' ? '#10b981' : '#ef4444'};
 color: white;
 padding: 14px 24px;
 border-radius: 16px;
 font-weight: 600;
 font-size: 14px;
 box-shadow: 0 10px 30px rgba(0,0,0,0.2);
 animation: slideInRight 0.3s ease;
 display: flex;
 align-items: center;
 gap: 12px;
 `;
 toast.innerHTML = `<i class="fas ${type === 'success' ? 'fa-check-circle' : 'fa-exclamation-circle'}" style="font-size: 20px;"></i> ${message}`;
 toastContainer.appendChild(toast);

 setTimeout(() => {
 toast.style.animation = 'slideOutRight 0.3s ease';
 setTimeout(() => toast.remove(), 300);
 }, 3000);
 }

 // Styles des animations de toast
 const style = document.createElement('style');
 style.textContent = `
 @keyframes slideInRight {
 from { transform: translateX(100%); opacity: 0; }
 to { transform: translateX(0); opacity: 1; }
 }
 @keyframes slideOutRight {
 from { transform: translateX(0); opacity: 1; }
 to { transform: translateX(100%); opacity: 0; }
 }
 `;
 document.head.appendChild(style);
 </script>

